function playTone(freq=520,duration=.09){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.045,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+duration);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+duration);o.onended=()=>c.close()}catch(e){}}
document.querySelectorAll('.btn').forEach(b=>b.addEventListener('click',()=>playTone(620,.07)));
document.querySelectorAll('.option input').forEach(i=>i.addEventListener('change',()=>{document.querySelectorAll('.option').forEach(x=>x.classList.remove('selected'));i.closest('.option').classList.add('selected');playTone(760,.06);updateProgress()}));
function updateProgress(){const all=[...document.querySelectorAll('.question')],done=all.filter(q=>q.querySelector('input:checked')).length,p=document.getElementById('progress');if(p)p.style.width=(done/all.length*100)+'%'}
function initQuizTimer(){const el=document.getElementById('timer'),form=document.getElementById('quizForm');if(!el||!form)return;let left=Number(el.dataset.seconds);const tick=()=>{el.textContent=left;el.classList.toggle('urgent',left<=15);if(left<=0){clearInterval(id);form.submit();return}left--};tick();const id=setInterval(tick,1000)}
